 public Map<String,Object> cancel(String c,long id,Map<String,Object> cmd,String actor){if(n(get(c,id),"fulfillment_model")==2){fulfillment.cancel(c,id,cmd,actor);return detail(c,id);}String reason=required(cmd,"reason",200);db.tx().execute(tx->{Map<String,Object>d=db.one("SELECT * FROM purchase_return WHERE company_code=? AND id=? FOR UPDATE",c,id);version(d,cmd);require(!Arrays.asList("CANCELED","COMPLETED").contains(d.get("state")),"本单已结束");boolean draft="DRAFT".equals(d.get("state"));db.jdbc.update("UPDATE purchase_return SET state=?,cancel_reason=?,control_version=control_version+1 WHERE company_code=? AND id=?",draft?"CANCELED":"CANCELING",reason,c,id);audit(c,id,"CANCEL_REQUEST",actor,reason);return null;});work.ready(c,id);return detail(c,id);}
