 private void continueAfterRelease(String c,long id){
  Map<String,Object> hint=get(c,id);
  db.tx().execute(tx->{db.one("SELECT id FROM po_info WHERE company_key=? AND id=? FOR UPDATE",c,hint.get("purchase_id"));Map<String,Object>d=db.one("SELECT * FROM purchase_return WHERE company_code=? AND id=? FOR UPDATE",c,id);if(!"CANCELED".equals(d.get("state")))return null;
   List<Map<String,Object>> pending=db.jdbc.queryForList("SELECT * FROM purchase_return_continuation WHERE company_code=? AND return_id=? AND state='WAIT_RELEASE' FOR UPDATE",c,id);if(pending.isEmpty())return null;Map<String,Object> pendingRow=pending.get(0);List<Map<String,Object>> remaining=new ArrayList<>();long qty=0;for(Map<String,Object> l:lines(c,id)){long q=n(l,"quantity")-n(l,"posted_quantity");if(q>0){Map<String,Object> copy=new LinkedHashMap<>(l);copy.put("quantity",q);remaining.add(copy);qty+=q;}}require(qty>0,"原单没有可继续的未出库数量");
   Map<String,Object> fields=new LinkedHashMap<>();for(String k:Arrays.asList("purchase_id","po_sn","supplier_sn","supplier_name","store_code","owner_code","real_store_code","outbound_mode","receiver_json","carrier_code"))fields.put(k,d.get(k));fields.putAll(map("company_code",c,"return_sn","CGT"+UUID.randomUUID().toString().replace("-",""),"request_key","CONTINUE_"+pendingRow.get("id"),"request_hash",pendingRow.get("request_hash"),"quantity",qty,"reason",pendingRow.get("reason"),"created_by",pendingRow.get("actor")));
   long child=db.insert("purchase_return",fields);for(Map<String,Object> l:remaining){Map<String,Object> row=new LinkedHashMap<>();for(String k:Arrays.asList("source_key","ticket_sn","sku_sn","goods_name","stock_unit","batch_code","inventory_type","quantity","source_quantity","purchase_price"))row.put(k,l.get(k));row.putAll(map("company_code",c,"return_id",child));db.insert("purchase_return_line",row);}
   db.jdbc.update("UPDATE purchase_return_continuation SET state='DRAFT_CREATED',child_id=? WHERE company_code=? AND id=?",child,c,pendingRow.get("id"));db.jdbc.update("UPDATE purchase_return SET last_error='',control_version=control_version+1 WHERE company_code=? AND id=?",c,id);audit(c,id,"CONTINUE_CREATED",text(pendingRow.get("actor")),"剩余已释放，已生成待审核后续退仓 "+fields.get("return_sn"));audit(c,child,"CREATE",text(pendingRow.get("actor")),"承接原退仓 "+d.get("return_sn")+" 未出库数量，须独立审核");return null;
  });
 }

 private Map<String,Object> stockCommand(Map<String,Object> d,List<Map<String,Object>> ls){List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> l:ls)rows.add(map("line_key",l.get("id"),"sku_sn",l.get("sku_sn"),"store_code",d.get("store_code"),"batch_code",l.get("batch_code"),"inventory_type",l.get("inventory_type"),"quantity",l.get("quantity"),"origin_relation",text(l.get("source_key")).startsWith("R")?"WMS_RECEIPT_"+text(l.get("source_key")).substring(1):text(l.get("source_key")).startsWith("S")?"PURCHASE_RECLAIM_"+text(l.get("source_key")).substring(1):l.get("ticket_sn")));return map("document_sn",d.get("return_sn"),"purpose","RETURN","actor",d.get("approved_by"),"lines",rows);}
 public void process(String c,long id){if(n(get(c,id),"fulfillment_model")==2){fulfillment.process(c,id);return;}String lease=UUID.randomUUID().toString();if(db.jdbc.update("UPDATE purchase_return SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND),attempts=attempts+1 WHERE company_code=? AND id=? AND state IN('APPROVING','APPROVED','CANCELING','ATTENTION','CANCELED') AND (lease_until IS NULL OR lease_until<NOW())",lease,c,id)==0)return;try{Map<String,Object>d=get(c,id);if("CANCELED".equals(d.get("state"))){continueAfterRelease(c,id);return;}List<Map<String,Object>> ls=lines(c,id);if(n(d,"stock_reserved")==0){if("CANCELING".equals(d.get("state"))){Map<String,Object> report=reply(stock.report(c,text(d.get("return_sn"))));if(!Boolean.TRUE.equals(report.get("exists"))){finishCancel(c,id);return;}}else reply(stock.execute(c,"reserve",stockCommand(d,ls)));db.jdbc.update("UPDATE purchase_return SET stock_reserved=1,state=IF(state='APPROVING','APPROVED',state),dispatch_state=IF(dispatch_state='UNSENT','PENDING',dispatch_state),last_error='' WHERE company_code=? AND id=?",c,id);d=get(c,id);}
   for(Map<String,Object> e:db.jdbc.queryForList("SELECT * FROM purchase_return_event WHERE company_code=? AND return_id=? AND state IN('PENDING','FAILED') ORDER BY id LIMIT 50",c,id)){try{Map<String,Object> receipt=object(e.get("payload_json"));reply(stock.execute(c,"post",map("document_sn",d.get("return_sn"),"message_id",e.get("message_id"),"lines",receipt.get("deltas"),"actor","WMS")));db.tx().execute(tx->{db.one("SELECT id FROM purchase_return WHERE company_code=? AND id=? FOR UPDATE",c,id);Map<String,Object> event=db.one("SELECT * FROM purchase_return_event WHERE company_code=? AND id=? FOR UPDATE",c,e.get("id"));if(!"POSTED".equals(event.get("state"))){for(Map<String,Object> l:(List<Map<String,Object>>)receipt.get("deltas"))db.jdbc.update("UPDATE purchase_return_line SET posted_quantity=posted_quantity+? WHERE company_code=? AND return_id=? AND id=?",l.get("quantity"),c,id,l.get("line_key"));db.jdbc.update("UPDATE purchase_return_event SET state='POSTED',last_error='' WHERE company_code=? AND id=?",c,e.get("id"));db.jdbc.update("UPDATE purchase_return SET posted_quantity=posted_quantity+?,last_error='' WHERE company_code=? AND id=?",e.get("quantity"),c,id);}return null;});}catch(Exception ex){db.jdbc.update("UPDATE purchase_return_event SET state='FAILED',last_error=? WHERE company_code=? AND id=?",safe(ex),c,e.get("id"));throw ex;}}
   d=get(c,id);if(n(d,"posted_quantity")==n(d,"quantity")&&n(d,"accepted_quantity")==n(d,"posted_quantity")){db.jdbc.update("UPDATE purchase_return SET state='COMPLETED',last_error='' WHERE company_code=? AND id=?",c,id);return;}
   if("CANCELING".equals(d.get("state"))){require(n(d,"receipt_review_pending")==0,"存在仓库出库回传冲突，请先核对并取得仓库更正回传");require(n(d,"accepted_quantity")==n(d,"posted_quantity"),"存在已确认出库未扣账明细，须先完成扣账");if(n(d,"receipt_final")==0&&n(d,"outbound_mode")==1&&!Arrays.asList("UNSENT","PENDING","FAILED","CANCELED").contains(d.get("dispatch_state")))interact(c,id,"CANCEL");d=get(c,id);if(n(d,"receipt_final")==1||n(d,"outbound_mode")==2||Arrays.asList("UNSENT","PENDING","FAILED","CANCELED").contains(d.get("dispatch_state"))){reply(stock.execute(c,"release",map("document_sn",d.get("return_sn"),"actor",d.get("approved_by"))));finishCancel(c,id);}return;}
   if(n(d,"outbound_mode")==2){Map<String,Object> r=map("return_sn",d.get("return_sn"),"message_id","VIRTUAL_FINAL","complete",true,"lines",ls,"status","DELIVERED","outbound_time",java.time.LocalDateTime.now().toString());List<Map<String,Object>> received=new ArrayList<>();for(Map<String,Object> l:ls)received.add(map("line_key",l.get("id"),"sku_sn",l.get("sku_sn"),"batch_code",l.get("batch_code"),"inventory_type",l.get("inventory_type"),"quantity",l.get("quantity")));r.put("lines",received);accept(c,id,r,0,true);}
   else if(Arrays.asList("PENDING","UNSENT").contains(d.get("dispatch_state")))interact(c,id,"CREATE");else if(Arrays.asList("SENDING","UNKNOWN").contains(d.get("dispatch_state")))interact(c,id,"QUERY");
  }catch(Exception e){db.jdbc.update("UPDATE purchase_return SET last_error=?,next_attempt_at=DATE_ADD(NOW(),INTERVAL LEAST(300,attempts*15) SECOND) WHERE company_code=? AND id=?",safe(e),c,id);}finally{db.jdbc.update("UPDATE purchase_return SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,id,lease);if(text(get(c,id).get("last_error")).isEmpty()&&db.jdbc.queryForObject("SELECT COUNT(*) FROM purchase_return_event WHERE company_code=? AND return_id=? AND state='PENDING'",Long.class,c,id)>0)work.ready(c,id);}}
 private String safe(Exception e){return e instanceof IllegalArgumentException?text(e.getMessage()).substring(0,Math.min(1000,text(e.getMessage()).length())):"服务执行未确认："+e.getClass().getSimpleName()+"，请沿用原单查询或重试";}
 private void finishCancel(String c,long id){db.tx().execute(tx->{db.one("SELECT id FROM po_info WHERE company_key=? AND id=(SELECT purchase_id FROM purchase_return WHERE company_code=? AND id=?) FOR UPDATE",c,c,id);db.one("SELECT id FROM purchase_return WHERE company_code=? AND id=? FOR UPDATE",c,id);db.jdbc.update("UPDATE purchase_return SET state='CANCELED',last_error='',control_version=control_version+1 WHERE company_code=? AND id=?",c,id);audit(c,id,"CANCEL_CONFIRMED","自动流程","未出库占用已按原来源释放，已出库和扣账保留");return null;});continueAfterRelease(c,id);}
 @SuppressWarnings("unchecked") private void interact(String c,long id,String action){Map<String,Object>d=get(c,id),payload=object(d.get("payload_json")),route=object(payload.get("route"));Map<String,Object> connection=action.equals("CREATE")?connections.usable(c,WmsStore.id(route.get("connection_id"))):connections.get(c,WmsStore.id(route.get("connection_id")));if(action.equals("CREATE")){Map<String,Object> current=outbound.resolve(c,payload);for(String k:Arrays.asList("connection_id","external_owner","external_warehouse"))require(text(current.get(k)).equals(text(route.get(k))),"原退仓映射已变化，请恢复配置后重试");require(db.jdbc.update("UPDATE purchase_return SET dispatch_state='SENDING' WHERE company_code=? AND id=? AND state='APPROVED' AND dispatch_state IN('PENDING','UNSENT')",c,id)==1,"当前退仓单已停止下发");}
  WmsProtocol.Wire wire=protocol.request(connection,connections.secret(connection),action,d,payload);long start=System.currentTimeMillis(),log=logs.start(c,WmsStore.id(connection.get("id")),id,text(d.get("return_sn")),"OUT","PURCHASE_RETURN_"+action,wire.body);boolean contacted=false;try{contacted=true;String response=WmsHttp.post(wire);WmsProtocol.Reply result=protocol.reply(action,response);require(result.documentSn.isEmpty()||result.documentSn.equals(d.get("return_sn")),"仓库响应原退仓单号不匹配");require(result.owner.isEmpty()||result.owner.equals(route.get("external_owner")),"仓库响应货主不匹配");require(result.warehouse.isEmpty()||result.warehouse.equals(route.get("external_warehouse")),"仓库响应仓库不匹配");require(text(d.get("external_order")).isEmpty()||result.externalOrder.isEmpty()||text(d.get("external_order")).equals(result.externalOrder),"仓库外部单号发生变化");String state=text(d.get("dispatch_state"));if(action.equals("CREATE"))state=result.success&&!result.externalOrder.isEmpty()?"ACCEPTED":result.success||!result.externalOrder.isEmpty()||result.code.toUpperCase(Locale.ROOT).matches(".*(DUPLICATE|EXISTS).*")||result.message.contains("已存在")||result.message.contains("重复")?"UNKNOWN":"FAILED";else if(action.equals("CANCEL"))state=result.success?"CANCELED":state;else if(result.success){require(result.documentSn.equals(d.get("return_sn"))&&!result.externalOrder.isEmpty(),"查询缺少当前退仓单身份");state=result.status.equals("CANCELED")?"CANCELED":Arrays.asList("NEW","ACCEPT","PARTDELIVERED","DELIVERED","CLOSED").contains(result.status)?"ACCEPTED":state;}String error=result.success?"":result.message;db.jdbc.update("UPDATE purchase_return SET dispatch_state=?,external_order=IF(?='',external_order,?),last_error=? WHERE company_code=? AND id=?",state,result.externalOrder,result.externalOrder,error,c,id);logs.finish(log,result.success?"SUCCESS":"FAILED",response,error,System.currentTimeMillis()-start);if(!result.success)db.jdbc.update("UPDATE purchase_return SET next_attempt_at=DATE_ADD(NOW(),INTERVAL LEAST(300,attempts*15) SECOND) WHERE company_code=? AND id=?",c,id);
  }catch(Exception e){if(action.equals("CREATE"))db.jdbc.update("UPDATE purchase_return SET dispatch_state=? WHERE company_code=? AND id=?",contacted?"UNKNOWN":"FAILED",c,id);logs.finish(log,"UNKNOWN","",safe(e),System.currentTimeMillis()-start);throw new IllegalArgumentException(safe(e));}}
 public Map<String,Object> query(String c,long id){Map<String,Object>d=get(c,id);if(n(d,"fulfillment_model")==2){fulfillment.query(c,id,n(fulfillment.latest(c,id),"id"));return detail(c,id);}require(n(d,"outbound_mode")==1&&d.get("payload_json")!=null,"本单尚无真实仓库任务");require(!Arrays.asList("PENDING","UNSENT","SENDING").contains(d.get("dispatch_state")),"仓库下发尚在执行，请刷新进度");String lease=UUID.randomUUID().toString();require(db.jdbc.update("UPDATE purchase_return SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 120 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,c,id)==1,"本单已有仓库交互进行中");try{interact(c,id,"QUERY");}finally{db.jdbc.update("UPDATE purchase_return SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,id,lease);}work.ready(c,id);return detail(c,id);}
 public String callback(String c,String key,Map<String,String> params,String body){Map<String,Object> connection=db.one("SELECT * FROM wms_connection WHERE company_code=? AND callback_key=?",c,key);try{Map<String,Object> parsed=protocol.part(connection,connections.secret(connection),params,body);if(fulfillment.contains(c,text(parsed.get("return_sn"))))return fulfillment.callback(c,key,params,body);}catch(IllegalArgumentException invalid){/* Legacy rejection is logged below. */}long start=System.currentTimeMillis(),log=logs.start(c,WmsStore.id(connection.get("id")),null,"","IN","PURCHASE_RETURN_RECEIPT",body);try{Map<String,Object> r=protocol.callback(connection,connections.secret(connection),params,body);Map<String,Object>d=db.one("SELECT * FROM purchase_return WHERE company_code=? AND return_sn=?",c,r.get("return_sn"));Map<String,Object> route=object(object(d.get("payload_json")).get("route"));require(WmsStore.id(route.get("connection_id"))==WmsStore.id(connection.get("id")),"回传连接与原退仓任务不匹配");db.jdbc.update("UPDATE wms_interaction_log SET task_id=?,ticket_sn=? WHERE id=?",d.get("id"),d.get("return_sn"),log);require(text(r.get("owner_code")).equals(route.get("external_owner"))&&text(r.get("warehouse_code")).equals(route.get("external_warehouse"))&&!text(r.get("external_order")).isEmpty()&&(text(d.get("external_order")).isEmpty()||text(d.get("external_order")).equals(r.get("external_order"))),"回传原仓库、货主或外部单号不匹配");try{accept(c,WmsStore.id(d.get("id")),r,log,false);}catch(IllegalArgumentException conflict){db.jdbc.update("UPDATE purchase_return SET receipt_review_pending=1,last_error=? WHERE company_code=? AND id=? AND state IN('APPROVED','CANCELING') AND receipt_final=0",safe(conflict),c,d.get("id"));throw conflict;}String response=new QimenProtocol().acknowledgement(true,"采购退仓出库已接收，后台按原批次扣账");logs.finish(log,"SUCCESS",response,"",System.currentTimeMillis()-start);return response;}catch(Exception e){String reason=safe(e);String response=new QimenProtocol().acknowledgement(false,reason);logs.finish(log,"FAILED",response,reason,System.currentTimeMillis()-start);return response;}}
 @SuppressWarnings("unchecked") public void accept(String c,long id,Map<String,Object> receipt,long log,boolean virtual){if(n(get(c,id),"fulfillment_model")==2){fulfillment.accept(c,n(fulfillment.latest(c,id),"id"),receipt,log,virtual);return;}db.tx().execute(tx->{Map<String,Object>d=db.one("SELECT * FROM purchase_return WHERE company_code=? AND id=? FOR UPDATE",c,id);String msg=required(receipt,"message_id",128),hash=digest(receipt);if(!virtual){Map<String,Object> route=object(object(d.get("payload_json")).get("route"));require(text(receipt.get("owner_code")).equals(route.get("external_owner"))&&text(receipt.get("warehouse_code")).equals(route.get("external_warehouse"))&&text(receipt.get("return_sn")).equals(d.get("return_sn"))&&(!text(receipt.get("external_order")).isEmpty()&&(text(d.get("external_order")).isEmpty()||text(receipt.get("external_order")).equals(d.get("external_order")))),"回传原单、仓库、货主或仓库单号不匹配");}List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM purchase_return_event WHERE company_code=? AND return_id=? AND message_id=?",c,id,msg);if(!old.isEmpty()){require(hash.equals(old.get(0).get("payload_hash")),"同一回传消息内容发生变化，请核对原消息");return null;}require(Arrays.asList("APPROVED","CANCELING").contains(d.get("state"))&&n(d,"receipt_final")==0,"本退仓单已结束，迟到回传须先核对原仓库交互，未扣账");require(n(d,"stock_reserved")==1&&(virtual||Arrays.asList("SENDING","UNKNOWN","ACCEPTED").contains(d.get("dispatch_state"))),"尚未确认原库存锁定或仓库未有效受理");Map<Long,Map<String,Object>> index=new TreeMap<>();for(Map<String,Object> l:lines(c,id))index.put(n(l,"id"),l);Map<Long,Long> totals=new TreeMap<>();for(Map<String,Object> l:(List<Map<String,Object>>)receipt.get("lines")){long key=WmsStore.id(l.get("line_key")),q=n(l,"quantity");Map<String,Object> original=index.get(key);require(original!=null&&text(original.get("sku_sn")).equals(l.get("sku_sn"))&&text(original.get("batch_code")).equals(l.get("batch_code"))&&text(original.get("inventory_type")).equals(l.get("inventory_type")),"回传SKU、原行、批次或正次品与退供来源不一致，未扣账");if(!virtual)require(text(l.get("owner_code")).isEmpty()||text(l.get("owner_code")).equals(receipt.get("owner_code")),"回传商品货主不一致");if(q>0)totals.merge(key,q,Math::addExact);}List<Map<String,Object>> deltas=new ArrayList<>();long total=0;for(Map.Entry<Long,Long> e:totals.entrySet()){Map<String,Object> l=index.get(e.getKey());require(n(l,"accepted_quantity")+e.getValue()<=n(l,"quantity"),"累计出库超过原退供行数量，未扣账");deltas.add(map("line_key",e.getKey(),"quantity",e.getValue()));total=Math.addExact(total,e.getValue());db.jdbc.update("UPDATE purchase_return_line SET accepted_quantity=accepted_quantity+? WHERE company_code=? AND id=?",e.getValue(),c,e.getKey());}Map<String,Object> retained=new LinkedHashMap<>(receipt);retained.put("deltas",deltas);if(!virtual)db.jdbc.update("UPDATE purchase_return SET external_order=IF(external_order='',?,external_order) WHERE company_code=? AND id=?",receipt.get("external_order"),c,id);db.insert("purchase_return_event",map("company_code",c,"return_id",id,"message_id",msg,"payload_hash",hash,"payload_json",db.encode(retained),"source_log_id",log,"quantity",total));db.jdbc.update("UPDATE purchase_return SET accepted_quantity=accepted_quantity+?,receipt_final=?,dispatch_state=IF(outbound_mode=1,'ACCEPTED','VIRTUAL'),receipt_review_pending=0,last_error='' WHERE company_code=? AND id=?",total,Boolean.TRUE.equals(receipt.get("complete"))?1:0,c,id);audit(c,id,"OUTBOUND_ACCEPTED",virtual?"虚拟自动流程":"WMS","确认出库增量 "+total+"；原消息 "+msg);return null;});work.ready(c,id);}
 public int scan(String c){List<Long> ids=db.jdbc.queryForList("SELECT r.id FROM purchase_return r WHERE r.company_code=? AND r.next_attempt_at<=NOW() AND (r.lease_until IS NULL OR r.lease_until<NOW()) AND (r.state IN('APPROVING','CANCELING') OR (r.state='CANCELED' AND EXISTS(SELECT 1 FROM purchase_return_continuation x WHERE x.company_code=r.company_code AND x.return_id=r.id AND x.state='WAIT_RELEASE')) OR (r.state='APPROVED' AND (r.dispatch_state IN('PENDING','SENDING','UNKNOWN') OR EXISTS(SELECT 1 FROM purchase_return_event e WHERE e.company_code=r.company_code AND e.return_id=r.id AND e.state IN('PENDING','FAILED'))))) ORDER BY r.next_attempt_at,r.id LIMIT 30",Long.class,c);for(long id:ids)work.ready(c,id);for(long id:db.jdbc.queryForList("SELECT r.id FROM purchase_return_execution_request x JOIN purchase_return r ON r.company_code=x.company_code AND r.id=x.return_id WHERE x.company_code=? AND x.state='WAIT_STOP' AND r.next_attempt_at<=NOW() AND (r.lease_until IS NULL OR r.lease_until<NOW()) ORDER BY x.id LIMIT 30",Long.class,c))work.ready(c,id);return ids.size();}
 private void attachFacts(String c,List<Map<String,Object>> documents){
  if(documents.isEmpty())return;Map<Long,Map<String,Object>> index=new HashMap<>();List<Object> args=new ArrayList<>();args.add(c);for(Map<String,Object>d:documents){index.put(n(d,"id"),d);args.add(d.get("id"));d.put("quantity_summary",new ArrayList<Map<String,Object>>());d.put("posted_amount",BigDecimal.ZERO);d.put("planned_amount",BigDecimal.ZERO);}String marks=String.join(",",Collections.nCopies(documents.size(),"?"));
  for(Map<String,Object> l:db.jdbc.queryForList("SELECT return_id,stock_unit,SUM(quantity) quantity,SUM(accepted_quantity) accepted_quantity,SUM(posted_quantity) posted_quantity,SUM(supplier_received_quantity) supplier_received_quantity,SUM(supplier_refused_quantity) supplier_refused_quantity,SUM(quantity*purchase_price) planned_amount,SUM(posted_quantity*purchase_price) posted_amount FROM purchase_return_line WHERE company_code=? AND return_id IN("+marks+") GROUP BY return_id,stock_unit",args.toArray())){Map<String,Object>d=index.get(n(l,"return_id"));((List<Map<String,Object>>)d.get("quantity_summary")).add(l);d.put("posted_amount",((BigDecimal)d.get("posted_amount")).add(new BigDecimal(l.get("posted_amount").toString())));d.put("planned_amount",((BigDecimal)d.get("planned_amount")).add(new BigDecimal(l.get("planned_amount").toString())));}
  for(Map<String,Object> x:db.jdbc.queryForList("SELECT return_id,COUNT(*) failures FROM purchase_return_event WHERE company_code=? AND return_id IN("+marks+") AND state='FAILED' GROUP BY return_id",args.toArray()))index.get(n(x,"return_id")).put("posting_failed_count",x.get("failures"));
  for(Map<String,Object> x:db.jdbc.queryForList("SELECT return_id,state FROM purchase_return_continuation WHERE company_code=? AND return_id IN("+marks+")",args.toArray()))index.get(n(x,"return_id")).put("continuation_state",x.get("state"));
  for(Map<String,Object> x:db.jdbc.queryForList("SELECT l.return_id,SUM(s.quantity*l.purchase_price) amount,SUM(s.quantity) quantity FROM purchase_return_reclaim_receipt_line s JOIN purchase_return_line l ON l.company_code=s.company_code AND l.id=s.return_line_id WHERE s.company_code=? AND l.return_id IN("+marks+") AND s.posted=1 GROUP BY l.return_id",args.toArray())){Map<String,Object>d=index.get(n(x,"return_id"));d.put("recovered_amount",x.get("amount"));d.put("recovered_quantity",x.get("quantity"));}
  for(Map<String,Object>d:documents){d.put("net_posted_amount",new BigDecimal(d.get("posted_amount").toString()).subtract(new BigDecimal(text(d.getOrDefault("recovered_amount",0)))));PurchaseReturnPresentation.enrich(d);d.put("funds_remaining",new BigDecimal(d.get("net_posted_amount").toString()).subtract(new BigDecimal(text(d.get("funds_amount")))).max(BigDecimal.ZERO));d.put("funds_over_recorded",new BigDecimal(text(d.get("funds_amount"))).compareTo(new BigDecimal(d.get("net_posted_amount").toString()))>0);}
if(fulfillment!=null)fulfillment.attach(c,documents);
 }

